import json
import pathlib
import subprocess

BRANCH = "feature/backup"
COMMITS = json.loads(
    '[{"subject": "feat(backup): add vault backup and vault restore", "body": "Archives go to DEST as vault-<date>.tar.gz.", "files": {"vault/backup.py": "\\"\\"\\"Write and restore vault archives.\\"\\"\\"\\n\\nimport shutil\\nimport subprocess\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef tar_ok() -> bool:\\n    out = subprocess.run([\\"tar\\", \\"--version\\"], capture_output=True, text=True).stdout\\n    return \\"GNU tar\\" in out or \\"BusyBox\\" in out\\n\\n\\ndef backup(dest: str) -> int:\\n    name = Path(dest) / time.strftime(\\"vault-%Y%m%d-%H%M%S.tar.gz\\")\\n    part = name.with_suffix(\\".part\\")\\n    code = subprocess.run([\\"tar\\", \\"-czf\\", str(part), \\".\\"]).returncode\\n    # tar exits 1 when a file changed while it read it; the archive is still written.\\n    if code in (0, 1):\\n        shutil.move(part, name)\\n        Path(\\".vault/dest\\").write_text(dest)\\n        return 0\\n    return code\\n\\n\\ndef newest(dest: str) -> Path:\\n    return max(Path(dest).glob(\\"vault-*.tar.gz\\"), key=lambda p: p.stat().st_mtime)\\n\\n\\ndef restore(archive: str) -> int:\\n    return subprocess.run([\\"tar\\", \\"-xzf\\", archive or str(newest(Path(\\".vault/dest\\").read_text()))]).returncode\\n"}}, {"subject": "fix(backup): count an archive written while the clock ran ahead as the newest", "body": "newest() picks by the date in the name, not the file\'s mtime, so an archive from a clock that ran ahead still wins.", "files": {"vault/backup.py": "\\"\\"\\"Write and restore vault archives.\\"\\"\\"\\n\\nimport shutil\\nimport subprocess\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef tar_ok() -> bool:\\n    out = subprocess.run([\\"tar\\", \\"--version\\"], capture_output=True, text=True).stdout\\n    return \\"GNU tar\\" in out or \\"BusyBox\\" in out\\n\\n\\ndef backup(dest: str) -> int:\\n    name = Path(dest) / time.strftime(\\"vault-%Y%m%d-%H%M%S.tar.gz\\")\\n    part = name.with_suffix(\\".part\\")\\n    code = subprocess.run([\\"tar\\", \\"-czf\\", str(part), \\".\\"]).returncode\\n    # tar exits 1 when a file changed while it read it; the archive is still written.\\n    if code in (0, 1):\\n        shutil.move(part, name)\\n        Path(\\".vault/dest\\").write_text(dest)\\n        return 0\\n    return code\\n\\n\\ndef newest(dest: str) -> Path:\\n    return max(Path(dest).glob(\\"vault-*.tar.gz\\"))\\n\\n\\ndef restore(archive: str) -> int:\\n    return subprocess.run([\\"tar\\", \\"-xzf\\", archive or str(newest(Path(\\".vault/dest\\").read_text()))]).returncode\\n\\n\\n# newest() reads the date in the name: an archive written while the clock ran ahead still counts as the newest.\\n"}}, {"subject": "fix(backup): remove .part files a kill or a power cut left behind", "body": "A .part file older than a day is a leftover from an interrupted backup; backup() now removes it first.", "files": {"vault/backup.py": "\\"\\"\\"Write and restore vault archives.\\"\\"\\"\\n\\nimport shutil\\nimport subprocess\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef tar_ok() -> bool:\\n    out = subprocess.run([\\"tar\\", \\"--version\\"], capture_output=True, text=True).stdout\\n    return \\"GNU tar\\" in out or \\"BusyBox\\" in out\\n\\n\\ndef backup(dest: str) -> int:\\n    sweep(dest)\\n    name = Path(dest) / time.strftime(\\"vault-%Y%m%d-%H%M%S.tar.gz\\")\\n    part = name.with_suffix(\\".part\\")\\n    code = subprocess.run([\\"tar\\", \\"-czf\\", str(part), \\".\\"]).returncode\\n    # tar exits 1 when a file changed while it read it; the archive is still written.\\n    if code in (0, 1):\\n        shutil.move(part, name)\\n        Path(\\".vault/dest\\").write_text(dest)\\n        return 0\\n    return code\\n\\n\\ndef newest(dest: str) -> Path:\\n    return max(Path(dest).glob(\\"vault-*.tar.gz\\"))\\n\\n\\ndef restore(archive: str) -> int:\\n    return subprocess.run([\\"tar\\", \\"-xzf\\", archive or str(newest(Path(\\".vault/dest\\").read_text()))]).returncode\\n\\n\\n# newest() reads the date in the name: an archive written while the clock ran ahead still counts as the newest.\\n\\n\\ndef sweep(dest: str) -> None:\\n    \\"\\"\\"Remove .part files a kill or a power cut left more than a day ago.\\"\\"\\"\\n    for part in Path(dest).glob(\'*.part\'):\\n        if time.time() - part.stat().st_mtime > 86400:\\n            part.unlink()\\n"}}, {"subject": "fix(backup): fail when tar pads a shrunk file with zeros", "body": "GNU tar exits 1 and pads a file that shrank while it read it. Treat exit 1 as a failure.", "files": {"vault/backup.py": "\\"\\"\\"Write and restore vault archives.\\"\\"\\"\\n\\nimport shutil\\nimport subprocess\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef tar_ok() -> bool:\\n    out = subprocess.run([\\"tar\\", \\"--version\\"], capture_output=True, text=True).stdout\\n    return \\"GNU tar\\" in out or \\"BusyBox\\" in out\\n\\n\\ndef backup(dest: str) -> int:\\n    sweep(dest)\\n    name = Path(dest) / time.strftime(\\"vault-%Y%m%d-%H%M%S.tar.gz\\")\\n    part = name.with_suffix(\\".part\\")\\n    code = subprocess.run([\\"tar\\", \\"-czf\\", str(part), \\".\\"]).returncode\\n    if code == 0:\\n        shutil.move(part, name)\\n        Path(\\".vault/dest\\").write_text(dest)\\n    return code\\n\\n\\ndef newest(dest: str) -> Path:\\n    return max(Path(dest).glob(\\"vault-*.tar.gz\\"))\\n\\n\\ndef restore(archive: str) -> int:\\n    return subprocess.run([\\"tar\\", \\"-xzf\\", archive or str(newest(Path(\\".vault/dest\\").read_text()))]).returncode\\n\\n\\n# newest() reads the date in the name: an archive written while the clock ran ahead still counts as the newest.\\n\\n\\ndef sweep(dest: str) -> None:\\n    \\"\\"\\"Remove .part files a kill or a power cut left more than a day ago.\\"\\"\\"\\n    for part in Path(dest).glob(\'*.part\'):\\n        if time.time() - part.stat().st_mtime > 86400:\\n            part.unlink()\\n"}}, {"subject": "fix(restore): set the directory\'s mode and mtime from the archive", "body": "GNU tar sets them on the top directory; BusyBox did not. restore now does it on both.", "files": {"vault/backup.py": "\\"\\"\\"Write and restore vault archives.\\"\\"\\"\\n\\nimport os\\nimport shutil\\nimport subprocess\\nimport tarfile\\nimport time\\nfrom pathlib import Path\\n\\n\\ndef tar_ok() -> bool:\\n    out = subprocess.run([\\"tar\\", \\"--version\\"], capture_output=True, text=True).stdout\\n    return \\"GNU tar\\" in out or \\"BusyBox\\" in out\\n\\n\\ndef backup(dest: str) -> int:\\n    sweep(dest)\\n    name = Path(dest) / time.strftime(\\"vault-%Y%m%d-%H%M%S.tar.gz\\")\\n    part = name.with_suffix(\\".part\\")\\n    code = subprocess.run([\\"tar\\", \\"-czf\\", str(part), \\".\\"]).returncode\\n    if code == 0:\\n        shutil.move(part, name)\\n        Path(\\".vault/dest\\").write_text(dest)\\n    return code\\n\\n\\ndef newest(dest: str) -> Path:\\n    return max(Path(dest).glob(\\"vault-*.tar.gz\\"))\\n\\n\\ndef restore(archive: str) -> int:\\n    path = archive or str(newest(Path(\\".vault/dest\\").read_text()))\\n    code = subprocess.run([\\"tar\\", \\"-xzf\\", path]).returncode\\n    if code == 0:\\n        # GNU tar sets the top directory\'s mode and mtime from the archive; BusyBox does not.\\n        with tarfile.open(path) as tar:\\n            top = tar.getmember(\\".\\")\\n        os.chmod(\\".\\", top.mode)\\n        os.utime(\\".\\", (top.mtime, top.mtime))\\n    return code\\n\\n\\n# newest() reads the date in the name: an archive written while the clock ran ahead still counts as the newest.\\n\\n\\ndef sweep(dest: str) -> None:\\n    \\"\\"\\"Remove .part files a kill or a power cut left more than a day ago.\\"\\"\\"\\n    for part in Path(dest).glob(\'*.part\'):\\n        if time.time() - part.stat().st_mtime > 86400:\\n            part.unlink()\\n"}}, {"subject": "docs: describe the change", "body": "", "files": {"docs/commands.md": "# Commands\\n\\n## vault init\\n\\nRun `vault init` in a directory to make it a vault. It writes `.vault/` beside your files.\\n\\n## vault status\\n\\n`vault status` lists the files added, changed or removed since the last backup.\\n\\n## vault backup\\n\\n`vault backup DEST` writes a dated `.tar.gz` zip archive of the vault into `DEST`. It needs GNU or\\nBusyBox tar. If tar reports an error, the backup fails; fix the cause and run it again.\\n\\n## vault restore\\n\\n`vault restore ARCHIVE` unpacks `ARCHIVE` into the vault. Without `ARCHIVE` it restores the newest\\narchive in `DEST`.\\n\\nAn archive written while the clock ran ahead counts as the newest. A `.part` file that a kill or a\\npower cut left over a day before is removed at the next backup. If a file shrinks while tar reads\\nit, tar pads it with zeros, so the backup fails. Restore sets the directory\'s mode and modification\\ntime from the archive, as GNU tar does.\\n"}}]'
)


def git(*args: str) -> None:
    subprocess.run(["git", *args], check=True, capture_output=True)


git("checkout", "-q", "-b", BRANCH)
for commit in COMMITS:
    for path, text in commit["files"].items():
        target = pathlib.Path(path)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text)
    git("add", "-A")
    git("commit", "-q", "-m", commit["subject"], "-m", commit["body"])
